/* Generated by scripts/build-fallback.php — edit resources/js/notify.js instead. */
/*
|--------------------------------------------------------------------------
| The bell, and the pop-up beside it
|--------------------------------------------------------------------------
| Polls one endpoint, keeps the badge and the dropdown in step with it, and
| raises a browser notification — the WhatsApp-looking one that slides in over
| whatever else is on the screen — for anything that arrived since the last
| poll.
|
| Three decisions worth knowing about:
|
|   • It only polls while the tab is visible. A hotel leaves this open on six
|     machines all night; polling a hidden tab every 25 seconds is thousands of
|     requests nobody will ever read. Coming back to the tab polls immediately,
|     so nothing is missed — it just arrives when somebody is there to see it.
|
|   • Permission is asked for on a click, never on load. Chrome and Firefox
|     both refuse a prompt that was not triggered by a gesture, and a refused
|     prompt counts as "denied" forever on some versions. So the footer button
|     appears only when asking is still possible, and disappears once it isn't.
|
|   • A pop-up is raised only for rows the server marks `fresh` — id greater
|     than the id this tab had last time. Without that, every poll would
|     re-announce the same booking, and the first thing anybody would do is
|     turn notifications off.
*/

(function () {
    'use strict';

    const root = document.querySelector('[data-notify]');
    if (!root) return;

    const feedUrl = root.getAttribute('data-feed');
    const readUrl = root.getAttribute('data-read');
    const allUrl = root.getAttribute('data-all');
    const every = Math.max(10, Number(root.getAttribute('data-poll')) || 25) * 1000;
    const workerUrl = root.getAttribute('data-worker') || '/sw-notify.js';

    const badge = root.querySelector('[data-notify-count]');
    const list = root.querySelector('[data-notify-list]');
    const readAll = root.querySelector('[data-notify-read-all]');
    const askButton = root.querySelector('[data-notify-permission]');
    const iconBank = root.querySelector('[data-notify-icons]');

    const token = (document.querySelector('meta[name="csrf-token"]') || {}).content || '';

    /* The highest id this tab has already seen. 0 means "first look" — and a
       first look never pops up, or signing in would fire eight notifications. */
    let seen = 0;

    // Same reason as the worker URL: the favicon is not at the domain root when
    // the app lives in a sub-folder.
    const iconUrl = workerUrl.replace(/sw-notify\.js$/, 'favicon-32.png');
    let timer = null;
    let swReg = null;
    let busy = false;

    /* ── Helpers ─────────────────────────────────────────────────────────── */

    function escapeHtml(value) {
        return String(value === null || value === undefined ? '' : value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    /** Once a day at most — the feed tidies old rows when this says so. */
    function shouldPrune() {
        try {
            const today = new Date().toISOString().slice(0, 10);
            if (localStorage.getItem('nova.notify.pruned') === today) return false;
            localStorage.setItem('nova.notify.pruned', today);
            return true;
        } catch (e) {
            return false;
        }
    }

    /**
     * The SVG for an icon, taken from the bank the page already rendered.
     *
     * Cloning beats re-drawing: the icon set lives in one Blade component, and
     * a JS copy of it would be a second set to keep in step.
     */
    function iconHtml(name) {
        if (!iconBank) return '';

        const found = iconBank.querySelector('[data-icon="' + String(name || '').replace(/[^a-z0-9-]/gi, '') + '"]')
            || iconBank.querySelector('[data-icon="bell"]');

        return found ? found.innerHTML : '';
    }

    /* ── Painting ────────────────────────────────────────────────────────── */

    function paintBadge(count) {
        if (!badge) return;

        badge.textContent = count > 99 ? '99+' : String(count);
        badge.hidden = count === 0;
    }

    function paintList(items) {
        if (!list) return;

        if (!items.length) {
            list.innerHTML = '<p class="nv-bell-empty">Nothing yet.</p>';
            return;
        }

        list.innerHTML = items.slice(0, 8).map(function (item) {
            const classes = ['nv-bell-item', 'is-' + item.level];
            if (item.unread) classes.push('is-unread');

            const body = item.body
                ? '<small>' + escapeHtml(item.body.length > 90 ? item.body.slice(0, 89) + '…' : item.body) + '</small>'
                : '';

            return '<a href="' + escapeHtml(item.url || allUrl) + '" class="' + classes.join(' ') + '">' +
                '<span class="nv-bell-icon">' + iconHtml(item.icon) + '</span>' +
                '<span class="nv-bell-text">' +
                '<strong>' + escapeHtml(item.title) + '</strong>' + body +
                '<em>' + escapeHtml(item.when) + '</em>' +
                '</span></a>';
        }).join('');
    }

    /* ── The browser pop-up ──────────────────────────────────────────────── */

    function canPopUp() {
        return 'Notification' in window && Notification.permission === 'granted';
    }

    function refreshAskButton() {
        if (!askButton) return;

        // Shown only while asking is still a thing that can happen: not when
        // the browser has no Notification API, not when it is already granted,
        // and not when the user has said no.
        askButton.hidden = !('Notification' in window) || Notification.permission !== 'default';
    }

    function popUp(item) {
        if (!canPopUp()) return;

        const options = {
            body: item.body || '',
            // One notification per row: a tag that repeats replaces the
            // previous pop-up instead of stacking five of them.
            tag: 'nova-' + item.id,
            icon: iconUrl,
            badge: iconUrl,
            data: { url: item.url || allUrl },
        };

        try {
            /*
             * Android Chrome throws on `new Notification(...)` and insists on
             * the service worker, so the worker is tried first and the plain
             * constructor is the fallback rather than the other way round.
             */
            if (swReg && swReg.showNotification) {
                swReg.showNotification(item.title, options);
                return;
            }

            const shown = new Notification(item.title, options);

            shown.onclick = function () {
                window.focus();
                if (item.url) window.location.href = item.url;
                shown.close();
            };
        } catch (e) {
            /* A browser that will not show it is not a reason to break the page. */
        }
    }

    /* ── Polling ─────────────────────────────────────────────────────────── */

    function poll() {
        if (busy || document.hidden) return;

        busy = true;

        const url = feedUrl +
            (feedUrl.indexOf('?') === -1 ? '?' : '&') +
            'since=' + seen +
            (shouldPrune() ? '&prune=1' : '');

        fetch(url, {
            headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
            credentials: 'same-origin',
        })
            .then(function (response) {
                if (!response.ok) throw new Error('feed');
                return response.json();
            })
            .then(function (data) {
                paintBadge(Number(data.unread) || 0);
                paintList(data.items || []);

                if (seen > 0) {
                    // Oldest first, so three bookings taken at once pop up in
                    // the order they were taken.
                    (data.items || [])
                        .filter(function (item) { return item.fresh; })
                        .reverse()
                        .forEach(popUp);
                }

                seen = Math.max(seen, Number(data.latest) || 0);
            })
            .catch(function () {
                /* A dropped connection is normal on a hotel's wifi. Try again
                   on the next tick rather than shouting about it. */
            })
            .then(function () {
                busy = false;
            });
    }

    function start() {
        stop();
        poll();
        timer = window.setInterval(poll, every);
    }

    function stop() {
        if (timer) window.clearInterval(timer);
        timer = null;
    }

    /* ── Wiring ──────────────────────────────────────────────────────────── */

    if (readAll) {
        readAll.addEventListener('click', function () {
            fetch(readUrl, {
                method: 'POST',
                headers: {
                    Accept: 'application/json',
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': token,
                    'X-Requested-With': 'XMLHttpRequest',
                },
                credentials: 'same-origin',
                body: '{}',
            })
                .then(function (response) { return response.ok ? response.json() : null; })
                .then(function (data) {
                    paintBadge(data ? Number(data.unread) || 0 : 0);
                    poll();
                })
                .catch(function () {});
        });
    }

    if (askButton) {
        askButton.addEventListener('click', function () {
            if (!('Notification' in window)) return;

            Notification.requestPermission().then(function () {
                refreshAskButton();

                if (canPopUp()) {
                    popUp({
                        id: 0,
                        title: 'Alerts are on',
                        body: 'This is what a notification will look like.',
                        url: allUrl,
                        level: 'info',
                    });
                }
            });
        });
    }

    document.addEventListener('visibilitychange', function () {
        if (document.hidden) {
            stop();
        } else {
            start();
        }
    });

    /*
     * The service worker is what makes the pop-up work on a phone. It is
     * registered quietly and its absence changes nothing — the desktop path
     * uses `new Notification` and does not need it.
     */
    if ('serviceWorker' in navigator && window.isSecureContext) {
        navigator.serviceWorker.register(workerUrl)
            .then(function (registration) { swReg = registration; })
            .catch(function () {});
    }

    refreshAskButton();
    start();
})();
